using System.IO.Compression;
using Tempest.Core;

var failed=0;var passed=0;
async Task Test(string name,Func<Task> body)
{
    try {await body();Console.WriteLine("PASS "+name);passed++;}
    catch(Exception e){Console.WriteLine("FAIL "+name+": "+e.Message);failed++;}
}
void Equal<T>(T expected,T actual){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"Expected {expected}; got {actual}");}
async Task Throws<T>(Func<Task> action) where T:Exception {try{await action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
string Fixture(){var p=Path.Combine(Path.GetTempPath(),"Tempest-tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(p);return p;}
Installation Paths(string root)=>new(Path.Combine(root,"Spotify"),Path.Combine(root,"Cli"),Path.Combine(root,"Config"),Path.Combine(root,"Data"));

await Test("INI reads only the requested section",()=>{Equal("two",Ini.Get("[Setting]\nversion=one\n[Backup]\nversion=two","Backup","version"));return Task.CompletedTask;});
await Test("INI edit preserves other sections and comments",()=>{var result=Ini.Set("[Setting]\n# keep\ncurrent_theme = old\n[Backup]\nversion = 123","Setting","current_theme","new");Equal("new",Ini.Get(result,"Setting","current_theme"));Equal("123",Ini.Get(result,"Backup","version"));Equal(true,result.Contains("# keep"));return Task.CompletedTask;});
await Test("INI inserts missing section",()=>{Equal("",Ini.Get(Ini.Set("[Setting]\ncurrent_theme=x","AdditionalOptions","extensions",""),"AdditionalOptions","extensions"));return Task.CompletedTask;});
await Test("Archive traversal is rejected",async()=>{var root=Fixture();var zip=Path.Combine(root,"bad.zip");using(var a=ZipFile.Open(zip,ZipArchiveMode.Create)){using var w=new StreamWriter(a.CreateEntry("../escape.txt").Open());w.Write("bad");}await Throws<IOException>(()=>Task.Run(()=>SafeFiles.ExtractZip(zip,Path.Combine(root,"out"))));Equal(false,File.Exists(Path.Combine(root,"escape.txt")));});
await Test("Normal archive extracts",()=>{var root=Fixture();var zip=Path.Combine(root,"ok.zip");using(var a=ZipFile.Open(zip,ZipArchiveMode.Create)){using var w=new StreamWriter(a.CreateEntry("folder/file.txt").Open());w.Write("ok");}SafeFiles.ExtractZip(zip,Path.Combine(root,"out"));Equal("ok",File.ReadAllText(Path.Combine(root,"out","folder","file.txt")));return Task.CompletedTask;});
await Test("Reject HTTP and lookalike hosts",()=>{Equal(false,Engine.AllowedDownload("http://github.com/file"));Equal(false,Engine.AllowedDownload("https://github.com.evil.invalid/file"));Equal(false,Engine.AllowedDownload("https://github.com@evil.invalid/file"));Equal(true,Engine.AllowedDownload("https://github.com/spicetify/cli/releases/download/v1/test.zip"));return Task.CompletedTask;});
await Test("Checkpoint restores changed and absent files",()=>{var root=Fixture();var folder=Path.Combine(root,"live");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"a"),"before");var absent=Path.Combine(root,"absent");var store=new RecoveryStore(Path.Combine(root,"recovery"),[folder,absent]);var cp=store.Save("test",[folder,absent],CancellationToken.None);File.WriteAllText(Path.Combine(folder,"a"),"after");Directory.CreateDirectory(absent);store.Restore(cp);Equal("before",File.ReadAllText(Path.Combine(folder,"a")));Equal(false,Directory.Exists(absent));Equal(1,store.List().Count);return Task.CompletedTask;});
await Test("Checkpoint rejects unapproved destinations",async()=>{var root=Fixture();var store=new RecoveryStore(Path.Combine(root,"recovery"),[Path.Combine(root,"allowed")]);await Throws<IOException>(()=>Task.Run(()=>store.Save("bad",[Path.Combine(root,"other")],CancellationToken.None)));});
await Test("Tampered recovery targets rejected before mutation",async()=>{var root=Fixture();var p=Path.Combine(root,"live");File.WriteAllText(p,"before");var store=new RecoveryStore(Path.Combine(root,"recovery"),[p]);var cp=store.Save("test",[p],CancellationToken.None);File.WriteAllText(p,"after");var tampered=cp with{Items=[new(Path.Combine(root,"outside"),"0",true,false)]};await Throws<IOException>(()=>Task.Run(()=>store.Restore(tampered)));Equal("after",File.ReadAllText(p));});
await Test("Incomplete checkpoint is not published",async()=>{var root=Fixture();var p=Path.Combine(root,"live");Directory.CreateDirectory(p);File.WriteAllText(Path.Combine(p,"a"),"x");var store=new RecoveryStore(Path.Combine(root,"recovery"),[p]);using var ct=new CancellationTokenSource();ct.Cancel();await Throws<OperationCanceledException>(()=>Task.Run(()=>store.Save("cancel",[p],ct.Token)));Equal(0,store.List().Count);});
await Test("Demo failure rolls back configuration",async()=>{var engine=new Engine(Paths(Fixture()),true);engine.SeedDemo();File.WriteAllText(engine.Paths.Ini,"[Setting]\ncurrent_theme = original");engine.FailNextDemo=true;await Throws<IOException>(()=>engine.Repair("apply",CancellationToken.None));Equal("original",Ini.Get(File.ReadAllText(engine.Paths.Ini),"Setting","current_theme"));Equal(1,engine.Recovery.List().Count);});
await Test("Cancellation restores previous state",async()=>{var engine=new Engine(Paths(Fixture()),true);engine.SeedDemo();var before=File.ReadAllText(engine.Paths.Ini);using var ct=new CancellationTokenSource();engine.Stage+=s=>{if(s.Contains("Demo: Preparing"))ct.Cancel();};await Throws<OperationCanceledException>(()=>engine.Repair("apply",ct.Token));Equal(before,File.ReadAllText(engine.Paths.Ini));});
await Test("Restore failure never removes CLI or config",async()=>{var paths=Paths(Fixture());var seed=new Engine(paths,true);seed.SeedDemo();var engine=new Engine(paths,false,new FakeRunner(1));await Throws<IOException>(()=>engine.RestoreVanilla(true,CancellationToken.None));Equal(true,File.Exists(paths.CliExe));Equal(true,File.Exists(paths.Ini));});
await Test("Successful exit without vanilla files is rejected",async()=>{var paths=Paths(Fixture());new Engine(paths,true).SeedDemo();var engine=new Engine(paths,false,new FakeRunner(0));await Throws<IOException>(()=>engine.RestoreVanilla(true,CancellationToken.None));Equal(true,File.Exists(paths.CliExe));});
await Test("Configuration reset targets AdditionalOptions",async()=>{var paths=Paths(Fixture());new Engine(paths,true).SeedDemo();File.WriteAllText(paths.Ini,"[Setting]\ncurrent_theme=broken\n[AdditionalOptions]\nextensions=broken.js\ncustom_apps=broken-app");var engine=new Engine(paths,false,new FakeRunner(0));await engine.Repair("reset",CancellationToken.None);var ini=File.ReadAllText(paths.Ini);Equal("",Ini.Get(ini,"Setting","current_theme"));Equal("",Ini.Get(ini,"AdditionalOptions","extensions"));Equal("",Ini.Get(ini,"AdditionalOptions","custom_apps"));});
await Test("Wrong configured Spotify path is rejected",async()=>{var paths=Paths(Fixture());var engine=new Engine(paths,true);engine.SeedDemo();File.WriteAllText(paths.Ini,"[Setting]\nspotify_path="+Path.Combine(Path.GetTempPath(),"different-spotify"));await Throws<IOException>(()=>engine.Repair("apply",CancellationToken.None));Equal(0,engine.Recovery.List().Count);});
await Test("Command runner propagates nonzero process exits",async()=>{if(!OperatingSystem.IsWindows())return;var r=await new CommandRunner().Run(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"cmd.exe"),["/d","/c","exit 7"],CancellationToken.None);Equal(7,r.ExitCode);});
await Test("Restore checkpoint creates an undo checkpoint",async()=>{var engine=new Engine(Paths(Fixture()),true);engine.SeedDemo();var cp=engine.Recovery.Save("saved",[engine.Paths.Config],CancellationToken.None);File.WriteAllText(engine.Paths.Ini,"changed");await engine.RestoreCheckpoint(cp,CancellationToken.None);Equal("marketplace",Ini.Get(File.ReadAllText(engine.Paths.Ini),"Setting","current_theme"));Equal(2,engine.Recovery.List().Count);});
await Test("Archive rejects Windows alternate data streams",async()=>{var root=Fixture();var zip=Path.Combine(root,"ads.zip");using(var a=ZipFile.Open(zip,ZipArchiveMode.Create)){using var w=new StreamWriter(a.CreateEntry("file.txt:hidden").Open());w.Write("bad");}await Throws<IOException>(()=>Task.Run(()=>SafeFiles.ExtractZip(zip,Path.Combine(root,"out"))));});
await Test("Malformed checkpoint does not break recovery listing",async()=>{var root=Fixture();var live=Path.Combine(root,"live");File.WriteAllText(live,"before");var store=new RecoveryStore(Path.Combine(root,"recovery"),[live]);var cp=store.Save("valid",[live],CancellationToken.None);var bad=cp with {Items=null!};File.WriteAllText(Path.Combine(store.Root,cp.Id,"checkpoint.json"),System.Text.Json.JsonSerializer.Serialize(bad));Equal(0,store.List().Count);await Throws<IOException>(()=>Task.Run(()=>store.Restore(bad)));Equal("before",File.ReadAllText(live));});
await Test("Duplicate recovery entries rejected before mutation",async()=>{var root=Fixture();var live=Path.Combine(root,"live");File.WriteAllText(live,"before");var store=new RecoveryStore(Path.Combine(root,"recovery"),[live]);var cp=store.Save("valid",[live],CancellationToken.None);File.WriteAllText(live,"after");var duplicate=cp with{Items=[cp.Items[0],cp.Items[0] with {Stored="1",Existed=false}]};await Throws<IOException>(()=>Task.Run(()=>store.Restore(duplicate)));Equal("after",File.ReadAllText(live));});

await Test("Tempest update detects a newer release",()=>{Equal(new Version(0,3,12),TempestUpdates.NewerVersion("{\"tag_name\":\"tempest-v0.3.12\",\"prerelease\":false}",new Version(0,3,2,0)));return Task.CompletedTask;});
await Test("Tempest update ignores equal and older versions",()=>{Equal<Version?>(null,TempestUpdates.NewerVersion("{\"tag_name\":\"tempest-v0.3.2\"}",new Version(0,3,2,0)));Equal<Version?>(null,TempestUpdates.NewerVersion("{\"tag_name\":\"tempest-v0.2.99\"}",new Version(0,3,2)));return Task.CompletedTask;});
await Test("Tempest update ignores draft preview and invalid tags",()=>{foreach(var json in new[]{"{\"tag_name\":\"tempest-v0.4.0\",\"draft\":true}","{\"tag_name\":\"tempest-v0.4.0\",\"prerelease\":true}","{\"tag_name\":\"other-v9.0.0\"}","{\"tag_name\":\"tempest-vbad\"}"})Equal<Version?>(null,TempestUpdates.NewerVersion(json,new Version(0,3,2)));return Task.CompletedTask;});

Console.WriteLine($"\n{passed} passed; {failed} failed.");return failed==0?0:1;

sealed class FakeRunner(int exitCode):ICommandRunner
{
    public Task<CommandResult> Run(string file,IEnumerable<string> args,CancellationToken token,Action<string>? log=null,IReadOnlyDictionary<string,string>? env=null)=>Task.FromResult(new CommandResult(exitCode,exitCode==0?"":"simulated subprocess failure"));
}
